(function(n){"use strict";n(document).ready(function(){n(document).on("click","button",function(){var t=n(this),a=t.attr("data-userid"),e=t.attr("data-buttontype"),d=n(t.children()[0]);if(e=="add-friend"){t.addClass("black");t.removeClass("green");t.attr("data-buttontype","unfriend");t.attr("data-tooltip","Unfriend");d.removeClass("fa-user-plus");d.addClass("fa-user-times");n.ajax({method:"POST",url:"/default/mark_friend/"+a}).done(function(t){n(".tooltipped").tooltip();n.web2py.flash(t)})}else if(e=="unfriend"){t.removeClass("black");t.addClass("green");t.attr("data-buttontype","add-friend");t.attr("data-tooltip","Add friend");d.removeClass("fa-user-times");d.addClass("fa-user-plus");n.ajax({method:"POST",url:"/default/unfriend/"+a}).done(function(t){n(".tooltipped").tooltip();n.web2py.flash(t)})}})})})(jQuery);